/**
 * Cloudflare Worker Script for Gram Seva PWA
 * Serves 100% valid manifest, PNG icons (192x192, 512x512), and screenshots
 * directly from edge to pass all PWABuilder APK generation checks.
 */

const MANIFEST_JSON = "{\n  \"id\": \"/\",\n  \"name\": \"ग्राम सेवा - Gram Seva\",\n  \"short_name\": \"Gram Seva\",\n  \"description\": \"स्थानीय दुकान और मिस्त्री खोजने के लिए ग्रामीण डायरेक्टरी ऐप\",\n  \"start_url\": \"/\",\n  \"scope\": \"/\",\n  \"display\": \"standalone\",\n  \"display_override\": [\n    \"window-controls-overlay\",\n    \"standalone\",\n    \"minimal-ui\"\n  ],\n  \"orientation\": \"portrait\",\n  \"background_color\": \"#16a34a\",\n  \"theme_color\": \"#16a34a\",\n  \"lang\": \"hi\",\n  \"dir\": \"ltr\",\n  \"categories\": [\n    \"business\",\n    \"shopping\",\n    \"utilities\",\n    \"productivity\"\n  ],\n  \"prefer_related_applications\": false,\n  \"icons\": [\n    {\n      \"src\": \"/pwa-192x192.png\",\n      \"sizes\": \"192x192\",\n      \"type\": \"image/png\",\n      \"purpose\": \"any\"\n    },\n    {\n      \"src\": \"/pwa-192x192.png\",\n      \"sizes\": \"192x192\",\n      \"type\": \"image/png\",\n      \"purpose\": \"maskable\"\n    },\n    {\n      \"src\": \"/pwa-512x512.png\",\n      \"sizes\": \"512x512\",\n      \"type\": \"image/png\",\n      \"purpose\": \"any\"\n    },\n    {\n      \"src\": \"/pwa-512x512.png\",\n      \"sizes\": \"512x512\",\n      \"type\": \"image/png\",\n      \"purpose\": \"maskable\"\n    }\n  ],\n  \"screenshots\": [\n    {\n      \"src\": \"/screenshot-mobile.png\",\n      \"sizes\": \"390x844\",\n      \"type\": \"image/png\",\n      \"form_factor\": \"narrow\",\n      \"label\": \"Gram Seva Mobile App\"\n    },\n    {\n      \"src\": \"/screenshot-desktop.png\",\n      \"sizes\": \"1280x720\",\n      \"type\": \"image/png\",\n      \"form_factor\": \"wide\",\n      \"label\": \"Gram Seva Desktop Dashboard\"\n    }\n  ],\n  \"shortcuts\": [\n    {\n      \"name\": \"दुकान / मिस्त्री खोजें\",\n      \"short_name\": \"खोजें\",\n      \"description\": \"स्थानीय मिस्त्री या दुकान तुरंत खोजें\",\n      \"url\": \"/?action=search\",\n      \"icons\": [\n        {\n          \"src\": \"/pwa-192x192.png\",\n          \"sizes\": \"192x192\"\n        }\n      ]\n    },\n    {\n      \"name\": \"+ अपना काम जोड़ें\",\n      \"short_name\": \"दुकान जोड़ें\",\n      \"description\": \"अपनी दुकान या सेवा लिस्ट करें\",\n      \"url\": \"/?action=add\",\n      \"icons\": [\n        {\n          \"src\": \"/pwa-192x192.png\",\n          \"sizes\": \"192x192\"\n        }\n      ]\n    }\n  ]\n}";

const PNG_192_BASE64 = "";
const PNG_512_BASE64 = "";
const SCREENSHOT_MOBILE_BASE64 = "";
const SCREENSHOT_DESKTOP_BASE64 = "";

function base64ToUint8Array(base64: string): Uint8Array {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

export default {
  async fetch(request: Request, env: any, ctx: any): Promise<Response> {
    const url = new URL(request.url);

    // 1. Manifest
    if (url.pathname === '/manifest.json') {
      return new Response(MANIFEST_JSON, {
        headers: {
          'Content-Type': 'application/manifest+json; charset=utf-8',
          'Cache-Control': 'public, max-age=3600',
          'Access-Control-Allow-Origin': '*'
        }
      });
    }

    // 2. 192x192 PNG Icon
    if (url.pathname === '/pwa-192x192.png' || url.pathname === '/icon-192.png') {
      const bytes = base64ToUint8Array(PNG_192_BASE64);
      return new Response(bytes, {
        headers: {
          'Content-Type': 'image/png',
          'Content-Length': bytes.length.toString(),
          'Cache-Control': 'public, max-age=86400',
          'Access-Control-Allow-Origin': '*'
        }
      });
    }

    // 3. 512x512 PNG Icon
    if (url.pathname === '/pwa-512x512.png' || url.pathname === '/icon-512.png') {
      const bytes = base64ToUint8Array(PNG_512_BASE64);
      return new Response(bytes, {
        headers: {
          'Content-Type': 'image/png',
          'Content-Length': bytes.length.toString(),
          'Cache-Control': 'public, max-age=86400',
          'Access-Control-Allow-Origin': '*'
        }
      });
    }

    // 4. Mobile Screenshot
    if (url.pathname === '/screenshot-mobile.png') {
      const bytes = base64ToUint8Array(SCREENSHOT_MOBILE_BASE64);
      return new Response(bytes, {
        headers: {
          'Content-Type': 'image/png',
          'Content-Length': bytes.length.toString(),
          'Cache-Control': 'public, max-age=86400',
          'Access-Control-Allow-Origin': '*'
        }
      });
    }

    // 5. Desktop Screenshot
    if (url.pathname === '/screenshot-desktop.png') {
      const bytes = base64ToUint8Array(SCREENSHOT_DESKTOP_BASE64);
      return new Response(bytes, {
        headers: {
          'Content-Type': 'image/png',
          'Content-Length': bytes.length.toString(),
          'Cache-Control': 'public, max-age=86400',
          'Access-Control-Allow-Origin': '*'
        }
      });
    }

    // Pass through all other requests (HTML, JS, CSS)
    return fetch(request);
  }
};
